from itertools import permutations

def is_between(a, b, c, order):
    pos_a = order.index(a)
    pos_b = order.index(b)
    pos_c = order.index(c)
    return (pos_a < pos_b < pos_c) or (pos_c < pos_b < pos_a)

def check_permutation(perm, constraints):
    for a, b, c in constraints:
        if not is_between(a, b, c, perm):
            return False
    return True

