def longest_valid_subsequence(nums, k):
    n = len(nums)

    if n == 1:
        return 1

    dp = [{} for _ in range(n)]

    for i in range(n):
        for j in range(i):
            remainder = (nums[j] + nums[i]) % k

            if remainder in dp[j]:
                dp[i][remainder] = dp[j][remainder] + 1
            else:
                dp[i][remainder] = 2

    max_length = 0
    for i in range(n):
        if dp[i]:
            max_length = max(max_length, max(dp[i].values()))

    if max_length == 0:
        max_length = 2

    return max_length

