def maxStrength(nums, k):
    n = len(nums)

    if k == 1:
        max_sum = float('-inf')
        for i in range(n):
            current_sum = 0
            for j in range(i, n):
                current_sum += nums[j]
                max_sum = max(max_sum, current_sum)
        return max_sum

    dp = {}

    def solve(idx, remaining, last_end):
        if remaining == 0:
            return 0

        if idx >= n:
            return float('-inf')

        if n - idx < remaining:
            return float('-inf')

        key = (idx, remaining, last_end)
        if key in dp:
            return dp[key]

        result = solve(idx + 1, remaining, last_end)

        current_sum = 0
        for j in range(idx, n):
            current_sum += nums[j]

            coeff = k - remaining
            weight = current_sum * coeff

            next_result = weight + solve(j + 1, remaining - 1, j)
            result = max(result, next_result)

        dp[key] = result
        return result

    return solve(0, k, -1)

