def solve(x1, y1, z1, x2, y2, z2, K):
    dx = abs(x2 - x1)
    dy = abs(y2 - y1)
    dz = abs(z2 - z1)

    distances = sorted([dx, dy, dz])

    d1, d2, d3 = distances[0], distances[1], distances[2]

    if d1 + d2 + d3 == 0:
        return 0

    if K == 1:
        return d1 + d2 + d3 + max(0, d2 - d1) + max(0, d3 - d2 - max(0, d2 - d1))

    total_dist = d1 + d2 + d3

    max_dist = max(d1, d2, d3)

    if max_dist <= K * (3 - 1):
        return total_dist

    if d1 == 0 and d2 == 0:
        return d3

    if d1 == 0 and d3 == 0:
        return d2

    if d2 == 0 and d3 == 0:
        return d1

    if d1 + d2 >= d3:
        return d1 + d2 + d3

    deficit = d3 - (d1 + d2)
    needed = ceil(deficit / K)

    return d1 + d2 + d3 + needed

