def is_good_sequence(X, K):
    Y = [0]
    for x in X:
        Y.append(Y[-1] + x)

    last_less = -1
    first_geq = N + 1

    for i in range(len(Y)):
        if Y[i] < K:
            last_less = i
        if Y[i] >= K and first_geq == N + 1:
            first_geq = i

    if last_less >= first_geq:
        return False
    return True

def solve(N, K, A):
    if N <= 10:
        for perm in permutations(A):
            if is_good_sequence(perm, K):
                return True, list(perm)
        return False, []

    A_sorted = sorted(A)

    if is_good_sequence(A_sorted, K):
        return True, A_sorted

    A_sorted_desc = sorted(A, reverse=True)
    if is_good_sequence(A_sorted_desc, K):
        return True, A_sorted_desc

    return False, []

