from math import comb

MOD = 998244353

def modinv(a, m=MOD):
    return pow(a, m - 2, m)

def solve(N, H, W):
    total_cells = H * W
    needed_cells = 4 * N * N

    if needed_cells > total_cells:
        return 0

    max_tiles_h = H // N
    max_tiles_w = W // N

    if max_tiles_h == 0 or max_tiles_w == 0:
        return 0

    count = 0

    for h1 in range(max_tiles_h + 1):
        for w1 in range(max_tiles_w + 1):
            tiles_placed = h1 * w1
            if tiles_placed > 4:
                continue

            remaining_tiles = 4 - tiles_placed

            if remaining_tiles == 0:
                ways = comb(max_tiles_h, h1) * comb(max_tiles_w, w1)
                count = (count + ways) % MOD
                continue

            covered_h = h1 * N
            covered_w = w1 * N

            remaining_h = H - covered_h
            remaining_w_in_covered_h = W - covered_w
            remaining_w = W

            valid = True

            if h1 > 0 and w1 > 0:
                extra_tiles_right = remaining_w_in_covered_h // N
                extra_tiles_bottom = remaining_h // N

                tiles_right = min(extra_tiles_right * h1, remaining_tiles)
                tiles_bottom = min(extra_tiles_bottom * w1, remaining_tiles)

                if tiles_right + tiles_placed >= 4 or tiles_bottom + tiles_placed >= 4:
                    ways = comb(max_tiles_h, h1) * comb(max_tiles_w, w1)
                    count = (count + ways) % MOD
            elif h1 > 0:
                if remaining_w >= N:
                    tiles_right_possible = (remaining_w // N) * h1
                    if tiles_right_possible >= remaining_tiles:
                        ways = comb(max_tiles_h, h1)
                        count = (count + ways) % MOD
            elif w1 > 0:
                if remaining_h >= N:
                    tiles_bottom_possible = (remaining_h // N) * w1
                    if tiles_bottom_possible >= remaining_tiles:
                        ways = comb(max_tiles_w, w1)
                        count = (count + ways) % MOD

    return count % MOD

