def trace(n, bars, start):
    pos = start
    for bar in bars:
        if pos == bar:
            pos = bar + 1
        elif pos == bar + 1:
            pos = bar
    return pos

def solve(n, m, p, q, bars):
    # Check if we can reach q from p without adding a bar
    if trace(n, bars, p) == q:
        return "OK"

    # Try adding a bar at each possible position
    for y in range(m + 1):
        # Try adding a bar connecting each pair of adjacent lines
        for x in range(1, n):
            # Create new bars list with the new bar inserted at position y
            new_bars = bars[:y] + [x] + bars[y:]

            # Check if this reaches q from p
            if trace(n, new_bars, p) == q:
                return f"{x} {y}"

    return "NG"

