import sys
from functools import lru_cache

def get_grundy(n):
    if n == 0:
        return 0

    digits = set()
    temp = n
    while temp > 0:
        digits.add(temp % 10)
        temp //= 10
    digits.discard(0)

    reachable = set()
    for d in digits:
        if d <= n:
            reachable.add(get_grundy(n - d))

    mex = 0
    while mex in reachable:
        mex += 1
    return mex

grundy_cache = {}
def compute_grundy(n):
    if n in grundy_cache:
        return grundy_cache[n]

    if n == 0:
        grundy_cache[n] = 0
        return 0

    digits = set()
    temp = n
    while temp > 0:
        digits.add(temp % 10)
        temp //= 10
    digits.discard(0)

    reachable = set()
    for d in digits:
