def count_snake_numbers(n):
    if n < 10:
        return 0

    s = str(n)
    first_digit = int(s[0])
    length = len(s)

    count = 0

    # Count all numbers with fewer digits where first digit is 1-9
    for d in range(1, 10):
        # For d-digit numbers starting with digit >= 2
        for start_digit in range(2, 10):
            count += start_digit ** (d - 1)

    # For numbers with same length as n, count carefully
    for d in range(1, length):
        for start_digit in range(1, 10):
            max_other = start_digit - 1
            if max_other >= 0:
                count += max_other ** (d - 1)

    # For numbers with same length as n and <= n
    def count_up_to_same_length(num_str):
        first = int(num_str[0])
        length = len(num_str)
        result = 0

        # Numbers starting with digit less than first
        for d in range(1, first):
            max_other = d - 1
            if max_other >= 0:
                result += max_other ** (length - 1)

        # Numbers starting with first digit
        # Need to count those <= num_str
        def count_recursive(pos, is_tight, current_first):
            if pos == length:
                return 1

            if is_tight:
                max_digit = int(num_str[pos])
            else:
                max_digit = current_first - 1

            result = 0
            for digit in range(0, max_digit + 1):
                if digit < current_first:
                    new_tight = is_tight and (digit == max_digit)
                    result += count_recursive(pos + 1, new_tight, current_first)

            return result

        result += count_recursive(1, True, first)
        return result

    count += count_up_to_same_length(s)

    return count

def count_snake_numbers_fast(n):
    if n < 10:
        return 0

    s = str(n)
    length = len(s)
    count = 0

    # Count all snake numbers with fewer digits
    for d in range(2, length):
        for first in range(1, 10):
            max_other = first - 1
            if max_other >= 0:
                count += max_other ** (d - 1)

    # Count snake numbers with same length as n
    first = int(s[0])

    # Count those starting with digits 1 to first-1
    for start in range(1, first):
        max_other = start - 1
        if max_other >= 0:
            count += max_other ** (length - 1)

    # Count those starting with first and <= n
    def dfs(pos, is_tight):
        if pos == length:
            return 1

        if is_tight:
            limit = int(s[pos])
        else:
            limit = first - 1

        total = 0
        for digit in range(0, min(limit + 1, first)):
            new_tight = is_tight and (digit == limit)
            total += dfs(pos + 1, new_tight)

        return total

    count += dfs(1, True)

    return count

