from collections import deque

def minimumOperations(x, y):
    if x == y:
        return 0

    queue = deque([(x, 0)])
    visited = {x}

    while queue:
        current, ops = queue.popleft()

        next_states = []

        if current % 11 == 0:
            next_states.append(current // 11)
        if current % 5 == 0:
            next_states.append(current // 5)
        next_states.append(current - 1)
        next_states.append(current + 1)

        for next_val in next_states:
            if next_val == y:
                return ops + 1

            if next_val not in visited and next_val > 0 and next_val <= 10**5:
                visited.add(next_val)
                queue.append((next_val, ops + 1))

    return -1

