def maxLengthNonDecreasing(nums):
    n = len(nums)
    if n == 1:
        return 1

    # dp[i] = maximum length of non-decreasing array ending at or before index i
    # with the last element being the sum of elements from some index j to i

    # We'll use a different approach: for each position, track all possible
    # (last_value, length) pairs that we can achieve

    # dp[i] = dictionary mapping last_value -> max_length
    dp = [dict() for _ in range(n)]

    # Base case: first element
    dp[0][nums[0]] = 1

    for i in range(1, n):
        # Option 1: Start a new segment at position i
        dp[i][nums[i]] = 1

        # Option 2: Extend previous segments or merge with current element
        for j in range(i):
            # Sum elements from j+1 to i
            current_sum = sum(nums[j+1:i+1])

            # For each state in dp[j], try to extend it
            for last_val, length in dp[j].items():
                if last_val <= current_sum:
                    # Can extend the non-decreasing sequence
                    if current_sum not in dp[i] or dp[i][current_sum] < length + 1:
                        dp[i][current_sum] = length + 1

        # Also consider extending from dp[j] without merging
        for j in range(i):
            for last_val, length in dp[j].items():
                if last_val <= nums[i]:
                    if nums[i] not in dp[i] or dp[i][nums[i]] < length + 1:
                        dp[i][nums[i]] = length + 1

    # Find the maximum length across all ending positions
    max_length = 1
    for i in range(n):
        if dp[i]:
            max_length = max(max_length, max(dp[i].values()))

    return max_length

def solve_optimized(nums):
    n = len(nums)
    if n == 1:
        return 1

    # More efficient approach using prefix sums
    # dp[i] = {last_value: max_length}
    dp = [dict() for _ in range(n)]

    # Precompute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    dp[0][nums[0]] = 1

    for i in range(1, n):
        # Start new sequence at position i
        dp[i][nums[i]] = 1

        # Try to extend or merge from previous positions
        for j in range(i):
            # Sum from j+1 to i (inclusive)
            segment_sum = prefix[i + 1] - prefix[j + 1]

            # Extend segments ending at j
            for last_val, length in dp[j].items():
                if last_val <= segment_sum:
                    if segment_sum not in dp[i] or dp[i][segment_sum] < length + 1:
                        dp[i][segment_sum] = length + 1

        # Also just append nums[i] after segments in dp[j]
        for j in range(i):
            for last_val, length in dp[j].items():
                if last_val <= nums[i]:
                    if nums[i] not in dp[i] or dp[i][nums[i]] < length + 1:
                        dp[i][nums[i]] = length + 1

    max_length = 1
    for i in range(n):
        if dp[i]:
            max_length = max(max_length, max(dp[i].values()))

    return max_length

