    memo = {}

    def can_win(coins_75, coins_10):
        if (coins_75, coins_10) in memo:
            return memo[(coins_75, coins_10)]

        # Try all possible ways to pick coins with total value 115
        can_current_player_win = False

        # Option 1: Pick a coins of value 75 and b coins of value 10
        # such that 75*a + 10*b = 115
        for a in range(min(coins_75, 115 // 75) + 1):
            remaining = 115 - 75 * a
            if remaining >= 0 and remaining % 10 == 0:
                b = remaining // 10
                if b <= coins_10:
                    new_75 = coins_75 - a
                    new_10 = coins_10 - b

                    # If opponent loses from the new state, current player wins
                    if not can_win(new_75, new_10):
                        can_current_player_win = True
                        break

        memo[(coins_75, coins_10)] = can_current_player_win
        return can_current_player_win

    # If Alice can win from initial state, Alice wins; otherwise Bob wins
    if can_win(x, y):
        return "Alice"
    else:
        return "Bob"

