def get_divisor_form_9(n):
    """
    A number has exactly 9 divisors if and only if:
    - It is of the form p^8 (where p is prime), or
    - It is of the form p^2 * q^2 (where p and q are distinct primes)
    """
    results = []

    # Form 1: p^8
    p = 2
    while p ** 8 <= n:
        results.append(p ** 8)
        p += 1
        # Skip non-primes
        while p <= n ** (1/8) + 1:
            is_prime = True
            if p < 2:
                is_prime = False
            elif p == 2:
                is_prime = True
            elif p % 2 == 0:
                is_prime = False
            else:
                i = 3
                while i * i <= p:
                    if p % i == 0:
                        is_prime = False
                        break
                    i += 2
            if is_prime:
                break
            p += 1

    # Form 2: p^2 * q^2
    # Generate all primes up to sqrt(sqrt(n))
    limit = int(n ** 0.25) + 1

    def sieve(limit):
        if limit < 2:
            return []
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, limit + 1, i):
                    is_prime[j] = False
        return [i for i in range(2, limit + 1) if is_prime[i]]

    primes = sieve(limit)

    for i in range(len(primes)):
        p = primes[i]
        p_sq = p * p
        if p_sq * p_sq > n:
            break
        for j in range(i + 1, len(primes)):
            q = primes[j]
            q_sq = q * q
            prod = p_sq * q_sq
            if prod > n:
                break
            results.append(prod)

    return sorted(set(results))

