def prime_factorize(n):
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

def get_signature(factors):
    sig = []
    for p in sorted(factors.keys()):
        sig.append((p, factors[p] % 2))
    return tuple(sig)

def factorize_edges(edges):
    edge_sigs = {}
    for edge, weight in edges.items():
        factors = prime_factorize(weight)
        sig = get_signature(factors)
        edge_sigs[edge] = sig
    return edge_sigs

def combine_sigs(sig1, sig2):
    combined = defaultdict(int)
    for p, parity in sig1:
        combined[p] = parity
    for p, parity in sig2:
        combined[p] = (combined[p] + parity) % 2
    return get_signature(combined)

def dfs(v, target, graph, edge_sigs, visited, current_sig):
    if v == target:
        return {current_sig}

    visited.add(v)
    sigs = set()

    for neighbor, edge in graph[v]:
        if neighbor not in visited:
            edge_sig = edge_sigs[edge]
            new_sig = combine_sigs(current_sig, edge_sig)
            result = dfs(neighbor, target, graph, edge_sigs, visited, new_sig)
            sigs.update(result)

    visited.remove(v)
    return sigs

