def solve(s, numOps):
    n = len(s)

    def canAchieve(maxLen):
        cost0 = 0
        cost1 = 0

        for i in range(n):
            expected0 = '0' if (i // maxLen) % 2 == 0 else '1'
            expected1 = '1' if (i // maxLen) % 2 == 0 else '0'

            if s[i] != expected0:
                cost0 += 1
            if s[i] != expected1:
                cost1 += 1

        return min(cost0, cost1) <= numOps

    def canAchieveAlternating():
        cost0 = 0
        cost1 = 0

        for i in range(n):
            expected0 = '0' if i % 2 == 0 else '1'
            expected1 = '1' if i % 2 == 0 else '0'

            if s[i] != expected0:
                cost0 += 1
            if s[i] != expected1:
                cost1 += 1

        return min(cost0, cost1) <= numOps

    if canAchieveAlternating():
        return 1

    left, right = 2, n
    result = n

    while left <= right:
        mid = (left + right) // 2
        if canAchieve(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

