    q_count = S.count('?')

    d_needed = H - 1 - d_count
    r_needed = W - 1 - r_count

    if d_needed < 0 or r_needed < 0 or d_needed + r_needed != q_count:
        return 0

    def get_paths():
        paths = []

        def generate(idx, path, d_left, r_left):
            if idx == n:
                if d_left == 0 and r_left == 0:
                    paths.append(path[:])
                return

            if S[idx] == 'D':
                path.append('D')
                generate(idx + 1, path, d_left, r_left)
                path.pop()
            elif S[idx] == 'R':
                path.append('R')
                generate(idx + 1, path, d_left, r_left)
                path.pop()
            else:
                if d_left > 0:
                    path.append('D')
                    generate(idx + 1, path, d_left - 1, r_left)
                    path.pop()
                if r_left > 0:
                    path.append('R')
                    generate(idx + 1, path, d_left, r_left - 1)
                    path.pop()

        generate(0, [], d_needed, r_needed)
        return paths

    paths = get_paths()

    if not paths:
        return 0

    painted = set()

    for path in paths:
        r, c = 0, 0
        painted.add((r, c))
        for move in path:
            if move == 'D':
                r += 1
            else:
                c += 1
            painted.add((r, c))

    return len(painted)

