def min_dyeing_steps(n, shades):
    if n == 0:
        return 0

    memo = {}

    def dp(index, current_shade):
        if index == n:
            return 0

        if (index, current_shade) in memo:
            return memo[(index, current_shade)]

        target_shade = shades[index]

        if target_shade < current_shade:
            return float('inf')

        min_steps = float('inf')

        j = index
        while j < n and shades[j] >= target_shade:
            j += 1

        steps_needed = 1 + dp(j, target_shade)
        min_steps = min(min_steps, steps_needed)

        memo[(index, current_shade)] = min_steps
        return min_steps

    result = dp(0, 0)
    return result

