        if not visited[leaf]:
            path = find_path_from_leaf(leaf)
            if path is None or len(path) != K:
                print("No")
                return
            paths.append(path)

    while len(paths) < N:
        unvisited = [i for i in range(1, N * K + 1) if not visited[i]]
        if not unvisited:
            break

        start = unvisited[0]
        path = find_path_from_leaf(start)
        if path is None or len(path) != K:
