def climbStairs(k):
    MOD = 10**9 + 7

    memo = {}

    def dp(current, jump, can_down):
        if current == k:
            return 1
        if current > k:
            return 0

        state = (current, jump, can_down)
        if state in memo:
            return memo[state]

        result = 0

        if can_down and current > 0:
            result += dp(current - 1, jump, False)

        next_stair = current + (1 << jump)
        if next_stair <= k + 60:
            result += dp(next_stair, jump + 1, True)

        result %= MOD
        memo[state] = result
        return result

    return dp(1, 0, True)

