def min_operations(n, a):
    memo = {}

    def solve(state):
        state_tuple = tuple(state)
        if state_tuple in memo:
            return memo[state_tuple]

        if len(state) == 0:
            return 0

        min_ops = float('inf')

        # Operation 2: Delete prefix of equal elements
        first = state[0]
        i = 1
        while i < len(state) and state[i] == first:
            i += 1
        new_state = state[i:]
        min_ops = min(min_ops, 1 + solve(new_state))

        # Operation 1: Swap adjacent elements
        for i in range(len(state) - 1):
            if state[i] != state[i + 1]:
                new_state = list(state)
                new_state[i], new_state[i + 1] = new_state[i + 1], new_state[i]
                min_ops = min(min_ops, 1 + solve(tuple(new_state)))

        memo[state_tuple] = min_ops
        return min_ops

    return solve(tuple(a))

