def compute_f(arr):
    if not arr:
        return 0

    from functools import lru_cache

    arr_tuple = tuple(arr)

    @lru_cache(maxsize=None)
    def min_ops(remaining):
        if not remaining:
            return 0

        remaining_list = list(remaining)
        min_val = min(remaining_list)
        max_val = max(remaining_list)

        best = float('inf')

        for l in range(min_val, max_val + 1):
            for r in range(l, max_val + 1):
                required = set(range(l, r + 1))
                available = set(remaining_list)

                if required.issubset(available):
                    new_remaining = tuple(x for x in remaining_list if x < l or x > r)
                    result = 1 + min_ops(new_remaining)
                    best = min(best, result)

        return best

    return min_ops(arr_tuple)

