def compute_cost(nums, l, r):
    total = 0
    for i in range(l, r + 1):
        if (i - l) % 2 == 0:
            total += nums[i]
        else:
            total -= nums[i]
    return total

def solve(nums):
    n = len(nums)
    if n == 1:
        return nums[0]

    dp = [float('-inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            cost = compute_cost(nums, j, i - 1)
            dp[i] = max(dp[i], dp[j] + cost)

    return dp[n]

