def can_reduce_to_zero(mountain_height, worker_times, max_time):
    total_reduction = 0
    for worker_time in worker_times:
        left, right = 0, mountain_height
        while left < right:
            mid = (left + right + 1) // 2
            if calculate_time_for_reduction(worker_time, mid) <= max_time:
                left = mid
            else:
                right = mid - 1
        total_reduction += left
        if total_reduction >= mountain_height:
            return True
    return total_reduction >= mountain_height

def min_seconds_to_reduce_mountain(mountain_height, worker_times):
    left, right = 0, mountain_height * max(worker_times) * (mountain_height + 1) // 2

    while left < right:
        mid = (left + right) // 2
        if can_reduce_to_zero(mountain_height, worker_times, mid):
            right = mid
        else:
            left = mid + 1

    return left

