def get_interior_angle(polygon, i):
    n = len(polygon)
    p1 = polygon[(i - 1) % n]
    p2 = polygon[i]
    p3 = polygon[(i + 1) % n]

    v1 = (p1[0] - p2[0], p1[1] - p2[1])
    v2 = (p3[0] - p2[0], p3[1] - p2[1])

    cross = v1[0] * v2[1] - v1[1] * v2[0]
    dot = v1[0] * v2[0] + v1[1] * v2[1]

    import math
    angle = math.atan2(cross, dot)
    return angle

