    for i in range(2, length + 1):
        count *= 9

    return count

def kth_neq_number(k):
    total = 0
    length = 1

    while total + count_neq_numbers_with_length(length) < k:
        total += count_neq_numbers_with_length(length)
        length += 1

    position_in_length = k - total

    def build_number(pos, current_length, last_digit):
        if current_length == length:
            return ""

        count_per_digit = 1
        for _ in range(length - current_length - 1):
            count_per_digit *= 9

        digit_index = 0
        for digit in range(10):
            if digit == last_digit:
                continue

            if digit_index * count_per_digit + count_per_digit >= pos:
                next_pos = pos - digit_index * count_per_digit
                return str(digit) + build_number(next_pos, current_length + 1, digit)

            digit_index += 1

        return ""

    result = ""
    for first_digit in range(1, 10):
        count_from_first = count_neq_numbers_with_length(length - 1)

        if position_in_length <= count_from_first:
            result = str(first_digit) + build_number(position_in_length, 1, first_digit)
            break

        position_in_length -= count_from_first

    return int(result)

def solve_optimized(k):
    total = 0
    length = 1

    while total + count_neq_numbers_with_length(length) < k:
        total += count_neq_numbers_with_length(length)
        length += 1

    position = k - total

    digits = []
    remaining = position

    for pos in range(length):
        if pos == 0:
            available_digits = list(range(1, 10))
        else:
            available_digits = [d for d in range(10) if d != digits[-1]]

        count_per_digit = 1
        for _ in range(length - pos - 1):
            count_per_digit *= 9

        digit_index = (remaining - 1) // count_per_digit
        digits.append(available_digits[digit_index])
        remaining = remaining - digit_index * count_per_digit

    return int("".join(map(str, digits)))

