from collections import Counter

def min_operations(n, k, arr):
    freq = Counter(arr)
    k_count = freq[k]
    max_other = max((count for val, count in freq.items() if val != k), default=0)

    if k_count > max_other:
        return 0

    min_ops = float('inf')

    for left in range(n + 1):
        for right in range(n + 1):
            if left + right >= n:
                continue

            subarray = arr[left:n - right]
            if not subarray:
                continue

            sub_freq = Counter(subarray)
            if k not in sub_freq:
                continue

            k_count_sub = sub_freq[k]
            max_other_sub = max((count for val, count in sub_freq.items() if val != k), default=0)

            if k_count_sub > max_other_sub:
                ops = (1 if left > 0 else 0) + (1 if right > 0 else 0)
                min_ops = min(min_ops, ops)

    return min_ops if min_ops != float('inf') else -1

