import sys
from functools import lru_cache

def solve(s, k):
    MOD = 10**9 + 7
    n = len(s)

    # Precompute which numbers are k-reducible
    max_bits = n
    reducible = [False] * (max_bits + 1)

    @lru_cache(maxsize=None)
    def steps_to_one(x):
        if x == 1:
            return 0
        return 1 + steps_to_one(bin(x).count('1'))

    for i in range(1, max_bits + 1):
        if steps_to_one(i) <= k:
            reducible[i] = True

    # DP to count numbers less than n with exactly c set bits
    # dp[pos][count][tight]
    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        if pos == n:
            if not started:
                return 0
            if count > 0 and count <= max_bits and reducible[count]:
                return 1
            return 0

        limit = int(s[pos]) if tight else 1
        result = 0

        for digit in range(0, limit + 1):
            new_started = started or (digit == 1)
            new_count = count + digit
            new_tight = tight and (digit == limit)
            result = (result + dp(pos + 1, new_count, new_tight, new_started)) % MOD

        return result

    return dp(0, 0, True, False)

