def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def is_product_equivalent(arr):
    if not arr:
        return False

    prod = 1
    for num in arr:
        prod *= num

    g = arr[0]
    for num in arr[1:]:
        g = gcd(g, num)

    l = arr[0]
    for num in arr[1:]:
        l = lcm(l, num)

    return prod == l * g

def longest_product_equivalent_subarray(nums):
    n = len(nums)
