    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD

    @lru_cache(maxsize=None)
    def dp(mask, pos):
        if pos == N:
            return 1

        result = 0
        for val in range(N):
            if mask & (1 << val):
                continue

            new_mask = mask | (1 << val)

            valid = True
            for l, r, x in conditions:
                if pos < l or pos > r:
                    continue
                if x != pos and (x < l or x > r or not (new_mask & (1 << x))):
                    continue

                max_val = -1
                max_pos = -1
                for p in range(l, min(pos + 1, r + 1)):
                    if new_mask & (1 << p):
                        bit_pos = 0
                        temp_mask = new_mask
                        for q in range(N):
                            if temp_mask & (1 << q):
                                if bit_pos == p:
                                    if q > max_val:
                                        max_val = q
                                        max_pos = p
                                    break
                                bit_pos += 1

                if pos == r:
                    actual_max_val = -1
                    actual_max_pos = -1
                    for p in range(l, r + 1):
                        bit_pos = 0
                        temp_mask = new_mask
                        for q in range(N):
                            if temp_mask & (1 << q):
                                if bit_pos == p:
                                    if q > actual_max_val:
                                        actual_max_val = q
                                        actual_max_pos = p
                                    break
                                bit_pos += 1

                    if actual_max_pos == x:
                        valid = False
                        break

            if valid:
                result = (result + dp(new_mask, pos + 1)) % MOD

        return result

    perm = [-1] * N

    def backtrack(pos, used):
        if pos == N:
            valid = True
            for l, r, x in conditions:
                max_val = max(perm[l:r+1])
                if perm[x] == max_val:
                    valid = False
                    break
            return 1 if valid else 0

        result = 0
        for val in range(1, N + 1):
            if val in used:
                continue

            perm[pos] = val
            used.add(val)

            valid = True
            for l, r, x in conditions:
                if pos < l or pos > r:
                    continue
                if pos == r:
                    max_val = max(perm[l:r+1])
                    if perm[x] == max_val:
