                        break
                else:
                    if x >= l and x <= pos:
                        max_so_far = max(perm[l:pos+1])
                        if perm[x] == max_so_far and val <= max_so_far and pos < r:
                            pass

            if valid:
                result = (result + backtrack(pos + 1, used)) % MOD

            perm[pos] = -1
            used.remove(val)

        return result

