from collections import deque, defaultdict

def parse_edges(edges_str):
    if not edges_str.strip():
        return []
    edges = []
    for edge in edges_str.split(';'):
        a, b = map(int, edge.split(','))
        edges.append([a, b])
    return edges

def build_graph(edges, n):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)
    return graph

def bfs_distances(graph, start, n):
    distances = [-1] * n
    distances[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if distances[neighbor] == -1:
                distances[neighbor] = distances[node] + 1
                queue.append(neighbor)
    return distances

def count_reachable(distances, k):
    return sum(1 for d in distances if d != -1 and d <= k)

def solve(edges1, edges2, k):
