    all_distances1 = []
    for i in range(n):
        all_distances1.append(bfs_distances(graph1, i, n))

    all_distances2 = []
    for i in range(m):
        all_distances2.append(bfs_distances(graph2, i, m))

    answer = []

    for i in range(n):
