        for node1 in range(n):
            for node2 in range(m):
                count = 0
                for node in range(n):
                    dist_in_tree1 = all_distances1[i][node]

                    dist_via_bridge = all_distances1[i][node1] + 1 + all_distances2[node2][node2]
                    if node1 < n:
                        for bridge_node2 in range(m):
                            dist_candidate = all_distances1[i][node1] + 1 + all_distances2[bridge_node2][node2]
                            dist_via_bridge = min(dist_via_bridge, dist_candidate)

                    min_dist = min(dist_in_tree1, all_distances1[i][node1] + 1 + all_distances2[node2][0])

                    for t2_node in range(m):
                        dist_via = all_distances1[i][node1] + 1 + all_distances2[node2][t2_node]
                        min_dist = min(min_dist, dist_via)

                    if min_dist <= k:
