        if val > target:
            return False
    for val in b_known:
        if val > target:
            return False

    # Calculate required sums for unknowns
    a_sum_needed = 0
    for val in a_known:
        a_sum_needed += (target - val)

    b_sum_needed = 0
    for val in b_known:
        b_sum_needed += (target - val)

    # Check if we can fill unknowns
    if a_unknown_count > 0:
        if a_sum_needed < 0:
            return False
    else:
        if a_sum_needed != 0:
            return False

    if b_unknown_count > 0:
        if b_sum_needed < 0:
            return False
    else:
        if b_sum_needed != 0:
            return False

    # Now check if we can match them up
    # We need to pair up elements from A and B to get target sum
    a_vals = []
    for val in a_known:
        a_vals.append(val)
    for _ in range(a_unknown_count):
        a_vals.append(-1)

    b_vals = []
    for val in b_known:
        b_vals.append(val)
    for _ in range(b_unknown_count):
        b_vals.append(-1)

    # Try to match: for each element in b_vals, try to find compatible element in a_vals
    b_vals_copy = b_vals[:]
    a_vals_copy = a_vals[:]

    for b_val in b_vals:
        if b_val == -1:
            # Can use any non-negative value <= target
            if a_vals_copy.count(-1) > 0:
                a_vals_copy.remove(-1)
            else:
                # Need to use a known a value
                found = False
                for a_val in a_vals_copy:
                    if a_val != -1 and a_val <= target:
                        a_vals_copy.remove(a_val)
                        found = True
                        break
                if not found:
                    return False
        else:
            # b_val is known, need a_val such that a_val + b_val = target
            needed_a = target - b_val
            if needed_a < 0:
                return False
            if needed_a in a_vals_copy:
                a_vals_copy.remove(needed_a)
            elif -1 in a_vals_copy:
                a_vals_copy.remove(-1)
            else:
                return False

    return True

