def solve(n, a):
    pos = {}
    for i in range(n):
        if a[i] not in pos:
            pos[a[i]] = []
        pos[a[i]].append(i)

    intervals = []
    for val, positions in pos.items():
        if len(positions) > 1:
            intervals.append((positions[0], positions[-1]))

    if not intervals:
        return len(set(a))

    intervals.sort()

    merged = [intervals[0]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    covered = set()
    for start, end in merged:
        for i in range(start, end + 1):
            covered.add(i)

    values_in_covered = set()
    for i in covered:
        values_in_covered.add(a[i])

    values_outside = set()
    for i in range(n):
        if i not in covered:
            values_outside.add(a[i])

    return len(values_in_covered) + len(values_outside)

