def solve(x, y, k):
    current_diff = abs(x - y)

    if current_diff == k:
        return 0

    total_stones = x + y

    if k > total_stones:
        return -1

    if (total_stones - k) % 2 != 0:
        return -1

    target_diff = k

    for steps in range(1, total_stones + 1):
        for transfer in range(steps + 1):
            if x >= transfer:
                new_x = x - transfer
                new_y = y + transfer
                if abs(new_x - new_y) == target_diff:
                    return steps

            if y >= transfer:
                new_x = x + transfer
                new_y = y - transfer
                if abs(new_x - new_y) == target_diff:
                    return steps

    return -1

