def get_kth_char(k):
    if k == 1:
        return 'a'

    length = 1
    iteration = 0

    while length < k:
        length *= 2
        iteration += 1

    def find_char(pos, iter_num):
        if iter_num == 0:
            return 'a'

        prev_length = 2 ** (iter_num - 1)

        if pos <= prev_length:
            return find_char(pos, iter_num - 1)
        else:
            char = find_char(pos - prev_length, iter_num - 1)
            return chr((ord(char) - ord('a') + 1) % 26 + ord('a'))

    return find_char(k, iteration)

