def can_match(s, p):
    star_idx = p.index('*')
    prefix = p[:star_idx]
    suffix = p[star_idx + 1:]

    prefix_len = len(prefix)
    suffix_len = len(suffix)

    for i in range(len(s)):
        if i + prefix_len > len(s):
            break
        if s[i:i + prefix_len] == prefix:
            for j in range(i + prefix_len, len(s) + 1):
                if j + suffix_len > len(s):
                    break
                if s[j:j + suffix_len] == suffix:
                    return True

    return False

