def solve(m, n, k):
    MOD = 10**9 + 7

    total_cells = m * n

    # Precompute factorials and inverse factorials for combinations
    fact = [1] * (total_cells + 1)
    for i in range(1, total_cells + 1):
        fact[i] = fact[i-1] * i % MOD

    # Function to compute modular inverse using Fermat's little theorem
    def mod_inverse(a, mod):
        return pow(a, mod - 2, mod)

    inv_fact = [1] * (total_cells + 1)
    inv_fact[total_cells] = mod_inverse(fact[total_cells], MOD)
    for i in range(total_cells - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def comb(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    # Count number of arrangements where two pieces are at distance d
    def count_pairs_at_distance(d):
        count = 0
        for i1 in range(m):
            for j1 in range(n):
                for i2 in range(m):
                    for j2 in range(n):
                        if (i1, j1) < (i2, j2):
                            if abs(i1 - i2) + abs(j1 - j2) == d:
                                count += 1
        return count

    # Calculate contribution of each distance
    total = 0

    # For each pair of positions
    for i1 in range(m):
        for j1 in range(n):
            for i2 in range(m):
                for j2 in range(n):
                    if (i1, j1) < (i2, j2):
                        distance = abs(i1 - i2) + abs(j1 - j2)

                        # Number of ways to arrange k pieces such that
                        # pieces are at (i1, j1) and (i2, j2)
                        # and remaining k-2 pieces in remaining total_cells-2 cells
                        remaining_cells = total_cells - 2
                        remaining_pieces = k - 2

                        if remaining_pieces <= remaining_cells:
                            ways = comb(remaining_cells, remaining_pieces)
                            total = (total + distance * ways) % MOD

    return total

