def countStableArrays(zero, one, limit):
    MOD = 10**9 + 7

    memo = {}

    def dp(z, o, last, consecutive):
        if z == 0 and o == 0:
            return 1
        if z < 0 or o < 0:
            return 0

        if (z, o, last, consecutive) in memo:
            return memo[(z, o, last, consecutive)]

        result = 0

        if last == 0:
            if consecutive < limit:
                result += dp(z - 1, o, 0, consecutive + 1)
            result += dp(z, o - 1, 1, 1)
        else:
            if consecutive < limit:
                result += dp(z, o - 1, 1, consecutive + 1)
            result += dp(z - 1, o, 0, 1)

        result %= MOD
        memo[(z, o, last, consecutive)] = result
        return result

    return (dp(zero - 1, one, 0, 1) + dp(zero, one - 1, 1, 1)) % (10**9 + 7)

