def maxScore(start, d):
    n = len(start)

    def canAchieveScore(minScore):
        positions = [(start[i], start[i] + d) for i in range(n)]

        def backtrack(index, lastChosen):
            if index == n:
                return True

            intervalStart, intervalEnd = positions[index]

            if lastChosen is None:
                for val in [intervalStart, intervalEnd]:
                    if backtrack(index + 1, val):
                        return True
            else:
                for val in [intervalStart, intervalEnd]:
                    if abs(val - lastChosen) >= minScore:
                        if backtrack(index + 1, val):
                            return True

            return False

        return backtrack(0, None)

    if d == 0:
        return 0

    left, right = 0, d
    result = 0

    while left <= right:
        mid = (left + right) // 2
        if canAchieveScore(mid):
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

