def max_kagamimochi(mochi):
    n = len(mochi)
    if n < 2:
        return 0

    left = 0
    right = n // 2

    def can_make(k):
        if k == 0:
            return True
        if 2 * k > n:
            return False

        used = [False] * n
        pairs = 0

        for i in range(n):
            if used[i]:
                continue

            for j in range(i + 1, n):
                if used[j]:
                    continue
                if mochi[i] * 2 <= mochi[j]:
                    used[i] = True
                    used[j] = True
                    pairs += 1
                    break

            if pairs == k:
                return True

        return pairs >= k

    result = 0
    while left <= right:
        mid = (left + right) // 2
        if can_make(mid):
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

