    if pos % 2 == 1:
        return 2
    return 0

def get_clockwise_direction(d):
    if d == 0:
        return 1
    elif d == 1:
        return 2
    elif d == 2:
        return 3
    else:
        return 0

def solve(grid):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

    max_length = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                for start_dir in range(4):
                    dr, dc = directions[start_dir]
                    length = 1
                    r, c = i + dr, j + dc
                    pos = 1
                    current_dir = start_dir
                    turned = False

                    while 0 <= r < n and 0 <= c < m:
                        expected = get_expected_value(pos)
                        if grid[r][c] != expected:
                            break
                        length += 1
                        pos += 1

                        nr1 = r + directions[current_dir][0]
                        nc1 = c + directions[current_dir][1]

                        can_continue_same = False
                        if 0 <= nr1 < n and 0 <= nc1 < m:
                            next_expected = get_expected_value(pos)
                            if grid[nr1][nc1] == next_expected:
                                can_continue_same = True

                        if can_continue_same:
                            r, c = nr1, nc1
                        elif not turned:
                            turned = True
                            new_dir = get_clockwise_direction(current_dir)
                            dr_new, dc_new = directions[new_dir]
                            nr2 = r + dr_new
                            nc2 = c + dc_new

                            if 0 <= nr2 < n and 0 <= nc2 < m:
