MOD = 998244353

def modinv(a, m=MOD):
    return pow(a, m - 2, m)

def solve():
    N = int(input())
    A = list(map(int, input().split()))

    total_balls = sum(A)

    # dp[mask] = probability that we reach state mask without ever seeing "101"
    # mask is a bitmask of which positions are 1
    dp = {}
    dp[0] = 1

    # balls_used[mask] = number of balls used to reach this mask
    balls_used = {}
    balls_used[0] = 0

    # BFS through states
    from collections import deque
    queue = deque([0])
    visited = {0}
    order = [0]

    while queue:
        mask = queue.popleft()
        for i in range(N):
            if mask & (1 << i):
                continue
            new_mask = mask | (1 << i)
            if new_mask not in visited:
                visited.add(new_mask)
                queue.append(new_mask)
                order.append(new_mask)

    def has_101(mask):
        s = ''.join('1' if mask & (1 << i) else '0' for i in range(N))
        return '101' in s

    prob_no_101 = 0

    for mask in order:
        if mask == 0:
            continue

        if has_101(mask):
            continue

        # Try to compute dp[mask]
        dp[mask] = 0

        for i in range(N):
            if mask & (1 << i):
                prev_mask = mask ^ (1 << i)
                if prev_mask in dp and not has_101(prev_mask):
                    # Count balls remaining when at prev_mask
                    balls_drawn = sum(A[j] for j in range(N) if prev_mask & (1 << j))
                    balls_remaining = total_balls - balls_drawn

                    prob_draw_i = (A[i] * modinv(balls_remaining)) % MOD
                    dp[mask] = (dp[mask] + dp[prev_mask] * prob_draw_i) % MOD

    # Sum probabilities of all final states (all balls drawn) without "101"
    for mask in dp:
        if bin(mask).count('1') == N and not has_101(mask):
            prob_no_101 = (prob_no_101 + dp[mask]) % MOD

    prob_101 = (1 - prob_no_101) % MOD
    print(prob_101)

solve()

