def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def max_distance_between_primes(nums):
    prime_indices = []
    for i, num in enumerate(nums):
        if is_prime(num):
            prime_indices.append(i)

    if len(prime_indices) < 2:
        return 0

    return prime_indices[-1] - prime_indices[0]

