def solve():
    line = sys.stdin.read().strip()
    parts = line.split('|')
    values = list(map(int, parts[0].split(',')))

    if len(parts) > 1 and parts[1]:
        edges = [list(map(int, edge.split(','))) for edge in parts[1].split(';')]
    else:
        edges = []

