    if n == 1:
        print(0)
        return

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def dfs(node, parent):
        children = [child for child in graph[node] if child != parent]

        if not children:
            return 0

        child_scores = []
        for child in children:
            child_score = dfs(child, node)
            child_scores.append(child_score)

        total_child_score = sum(child_scores)

        take_current = total_child_score + values[node]
        skip_current = total_child_score

        any_child_is_leaf = False
        for child in children:
            child_children = [c for c in graph[child] if c != node]
            if not child_children:
                any_child_is_leaf = True
                break

        if any_child_is_leaf:
            return max(take_current, skip_current)

        return take_current

    def dfs_optimized(node, parent):
        children = [child for child in graph[node] if child != parent]

        if not children:
            return 0

        total = 0
        has_leaf_child = False

        for child in children:
            child_children = [c for c in graph[child] if c != node]
            if not child_children:
                has_leaf_child = True
            total += dfs_optimized(child, node)

        if has_leaf_child:
            option1 = total + values[node]
            option2 = total
            return max(option1, option2)
        else:
            return total + values[node]

