def count_distinct_pairs(n):
    pairs = set()

    for mask in range(1 << n):
        s = bin(mask)[2:].zfill(n)

        zeros = 0
        x = 0
        for c in s:
            if c == '1':
                x += zeros
            else:
                zeros += 1

        ones = 0
        y = 0
        for c in reversed(s):
            if c == '0':
                y += ones
            else:
                ones += 1

        pairs.add((x, y))

    return len(pairs)

def solve_large(n):
    if n <= 20:
        return count_distinct_pairs(n)

    memo = {}

    def dp(pos, zeros, ones, x, y):
        if pos == n:
            return {(x, y)}

        key = (pos, zeros, ones, x, y)
        if key in memo:
            return memo[key]

        result = set()

        result |= dp(pos + 1, zeros + 1, ones, x, y)
        result |= dp(pos + 1, zeros, ones + 1, x + zeros, y + ones)

        memo[key] = result
        return result

    pairs = dp(0, 0, 0, 0, 0)
    return len(pairs)

