def min_operations(n, p):
    if p == list(range(1, n + 1)):
        return 0

    for k in range(1, n + 1):
        new_p = p[:]
        if k >= 2:
            new_p[:k-1] = sorted(new_p[:k-1])
        if k <= n - 1:
            new_p[k:] = sorted(new_p[k:])
        if new_p == list(range(1, n + 1)):
            return 1

    for k1 in range(1, n + 1):
        new_p1 = p[:]
        if k1 >= 2:
            new_p1[:k1-1] = sorted(new_p1[:k1-1])
        if k1 <= n - 1:
            new_p1[k1:] = sorted(new_p1[k1:])

        for k2 in range(1, n + 1):
            new_p2 = new_p1[:]
            if k2 >= 2:
                new_p2[:k2-1] = sorted(new_p2[:k2-1])
            if k2 <= n - 1:
                new_p2[k2:] = sorted(new_p2[k2:])
            if new_p2 == list(range(1, n + 1)):
                return 2

    return 3

