def solve(n):
    MOD = 998244353

    memo = {}

    def minimax(round_num, current_score, is_alice_turn):
        if round_num > n:
            return (current_score, current_score)

        power = 1 << (round_num - 1)

        state = (round_num, current_score, is_alice_turn)
        if state in memo:
            return memo[state]

        option1_score = current_score + power
        option2_score = current_score - power

        min_x1, max_y1 = minimax(round_num + 1, option1_score, not is_alice_turn)
        min_x2, max_y2 = minimax(round_num + 1, option2_score, not is_alice_turn)

        x1 = max(option1_score, min_x1)
        y1 = min(option1_score, max_y1)

        x2 = max(option2_score, min_x2)
        y2 = min(option2_score, max_y2)

        if is_alice_turn:
            if (x1 - y1) < (x2 - y2):
                result = (x1, y1)
            elif (x1 - y1) > (x2 - y2):
                result = (x2, y2)
            else:
                result = (x1, y1)
        else:
            if (x1 - y1) > (x2 - y2):
                result = (x1, y1)
            elif (x1 - y1) < (x2 - y2):
                result = (x2, y2)
            else:
                result = (x1, y1)

        memo[state] = result
        return result

    max_x, min_y = minimax(1, 0, True)
    return (max_x - min_y) % MOD

