def get_prime_factorization(n):
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

def get_reduced_form(n):
    if n == 1:
        return (1, 1)

    factors = get_prime_factorization(n)

    g = 1
    for prime, count in factors.items():
        g *= prime ** (count % 2)

    return (g, n // (g * g))

