def solve():
    line = input().strip()
    parts = line.split()
    n = int(parts[0])

    matrix_str = parts[1]
    rows = matrix_str.split(';')
    fruits = []
    for row_str in rows:
        row = list(map(int, row_str.split(',')))
        fruits.append(row)

    # DP approach: track all three children's positions simultaneously
    # State: (row1, col1, row2, col2, row3, col3, step)
    # But we can optimize by noting that after k steps, row_i + col_i = k + starting_row + starting_col
    # Child 1 starts at (0,0): row1 + col1 = step
    # Child 2 starts at (0,n-1): row2 + col2 = step + n - 1
    # Child 3 starts at (n-1,0): row3 + col3 = step + n - 1

    memo = {}

    def get_next_positions(r, c, child_type):
        # child_type: 0 for child1, 1 for child2, 2 for child3
        next_pos = []
        if child_type == 0:  # (0,0) -> moves: (i+1,j+1), (i+1,j), (i,j+1)
            if r + 1 < n and c + 1 < n:
                next_pos.append((r + 1, c + 1))
            if r + 1 < n:
                next_pos.append((r + 1, c))
            if c + 1 < n:
                next_pos.append((r, c + 1))
        elif child_type == 1:  # (0,n-1) -> moves: (i+1,j-1), (i+1,j), (i+1,j+1)
            if r + 1 < n and c - 1 >= 0:
                next_pos.append((r + 1, c - 1))
            if r + 1 < n:
                next_pos.append((r + 1, c))
            if r + 1 < n and c + 1 < n:
                next_pos.append((r + 1, c + 1))
        elif child_type == 2:  # (n-1,0) -> moves: (i-1,j+1), (i,j+1), (i+1,j+1)
            if r - 1 >= 0 and c + 1 < n:
                next_pos.append((r - 1, c + 1))
            if c + 1 < n:
                next_pos.append((r, c + 1))
            if r + 1 < n and c + 1 < n:
                next_pos.append((r + 1, c + 1))
        return next_pos

    def dp(r1, c1, r2, c2, r3, c3, step):
        if step == n - 1:
            result = 0
            if r1 == n - 1 and c1 == n - 1:
                result += fruits[r1][c1]
            if r2 == n - 1 and c2 == n - 1:
                if not (r1 == n - 1 and c1 == n - 1):
                    result += fruits[r2][c2]
            if r3 == n - 1 and c3 == n - 1:
                if not ((r1 == n - 1 and c1 == n - 1) or (r2 == n - 2 and c2 == n - 1)):
                    result += fruits[r3][c3]
            return result

        state = (r1, c1, r2, c2, r3, c3, step)
        if state in memo:
            return memo[state]

        max_fruits = 0

        for nr1, nc1 in get_next_positions(r1, c1, 0):
            for nr2, nc2 in get_next_positions(r2, c2, 1):
                for nr3, nc3 in get_next_positions(r3, c3, 2):
                    current = 0
                    positions = {}
                    if (nr1, nc1) not in positions:
                        positions[(nr1, nc1)] = []
                    positions[(nr1, nc1)].append(0)
                    if (nr2, nc2) not in positions:
                        positions[(nr2, nc2)] = []
                    positions[(nr2, nc2)].append(1)
                    if (nr3, nc3) not in positions:
                        positions[(nr3, nc3)] = []
                    positions[(nr3, nc3)].append(2)

                    for pos, children in positions.items():
                        current += fruits[pos[0]][pos[1]]

                    current += dp(nr1, nc1, nr2, nc2, nr3, nc3, step + 1)
                    max_fruits = max(max_fruits, current)

        memo[state] = max_fruits
        return max_fruits

    result = dp(0, 0, 0, n - 1, n - 1, 0, 0)
    print(result)

