from functools import lru_cache

MOD = 998244353

def solve(S):
    n = len(S)
    chars = "0123456789+()"

    @lru_cache(maxsize=None)
    def dp(pos, state):
        # state: (count, sum)
        # Returns (number of valid ways, sum of evaluations)
        if pos == n:
            result = parse_expr(0, state)
            if result is None:
                return (0, 0)
            final_pos, val = result
            if final_pos == len(state):
                return (1, val)
            else:
                return (0, 0)

        if S[pos] == '?':
            total_count = 0
            total_sum = 0
            for c in chars:
                count, s = dp(pos + 1, state + c)
                total_count = (total_count + count) % MOD
                total_sum = (total_sum + s) % MOD
            return (total_count, total_sum)
        else:
            return dp(pos + 1, state + S[pos])

    def parse_expr(pos, s):
        result = parse_term(pos, s)
        if result is None:
            return None
        pos, val = result

        while pos < len(s) and s[pos] == '+':
            result2 = parse_term(pos + 1, s)
            if result2 is None:
                return (pos, val)
            pos, val2 = result2
            val = val + val2

        return (pos, val)

    def parse_term(pos, s):
        if pos >= len(s):
            return None

        if s[pos] == '(':
            result = parse_expr(pos + 1, s)
            if result is None:
                return None
            pos, val = result
            if pos >= len(s) or s[pos] != ')':
                return None
            return (pos + 1, val)

        result = parse_number(pos, s)
        if result is not None:
            return result

        result = parse_digit(pos, s)
        return result

    def parse_number(pos, s):
        if pos >= len(s) or s[pos] != '0':
            return None
        result = parse_digit(pos + 1, s)
        if result is None:
            return None
        pos2, d = result
        val = d
        return (pos2, val)

    def parse_digit(pos, s):
        if pos >= len(s):
            return None
        if s[pos] in '0123456789':
            return (pos + 1, int(s[pos]))
        return None

    return dp(0, "")

