MOD = 998244353

def count_arrays(M):
    bits = M.bit_length()

    # Find all valid numbers <= M
    valid = []
    for i in range(1, M + 1):
        valid.append(i)
        if len(valid) > 60:
            break

    # For small M, use direct DP
    if M <= 60:
        valid = list(range(1, M + 1))
        n = len(valid)

        # dp[mask] = number of ways to select disjoint subset with OR = mask
        dp = {}
        dp[0] = 1

        for num in valid:
            new_dp = dp.copy()
            for mask, cnt in dp.items():
                if mask & num == 0:
                    new_mask = mask | num
                    new_dp[new_mask] = (new_dp.get(new_mask, 0) + cnt) % MOD
            dp = new_dp

        # Count arrays (ordered sequences)
        # For each subset, count permutations
        result = 0
        for mask, cnt in dp.items():
            if mask == 0:
                continue
            # Count how many numbers in this subset
            subset = []
            for num in valid:
                if (mask | num) == mask and (mask & ~num) < mask:
                    is_in = True
                    for other in subset:
                        if num & other != 0:
                            is_in = False
                            break
                    if is_in:
                        can_add = True
                        for other in subset:
                            if num & other != 0:
                                can_add = False
                                break
                        if can_add:
                            subset.append(num)

        # Use inclusion-exclusion with DP on subsets
        memo = {}

        def solve(used_mask):
            if used_mask in memo:
                return memo[used_mask]

            # Count ordered sequences using numbers with OR in used_mask
            subset = []
            for num in valid:
                if (used_mask & num) == num:
                    ok = True
                    for s in subset:
                        if s & num != 0:
                            ok = False
                            break
                    if ok:
                        subset.append(num)

            # DP: count sequences
            dp_seq = [0] * (1 << len(subset))
            dp_seq[0] = 1

            for i in range(1 << len(subset)):
                if dp_seq[i] == 0:
                    continue
                for j in range(len(subset)):
                    if i & (1 << j):
                        continue
                    # Check if subset[j] is disjoint with all selected
                    ok = True
                    for k in range(len(subset)):
                        if i & (1 << k):
                            if subset[j] & subset[k] != 0:
                                ok = False
                                break
                    if ok:
                        dp_seq[i | (1 << j)] = (dp_seq[i | (1 << j)] + dp_seq[i]) % MOD

            res = sum(dp_seq) % MOD - 1
            memo[used_mask] = res
            return res

        return solve((1 << bits) - 1) % MOD

    # For larger M, use digit DP
    memo = {}

    def dp(pos, tight, or_mask, has_any):
        if (pos, tight, or_mask, has_any) in memo:
            return memo[(pos, tight, or_mask, has_any)]

        if pos == -1:
            return 1 if has_any else 0

        limit = ((M >> pos) & 1) if tight else 1
        result = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_or = or_mask | (digit << pos) if has_any or digit == 1 else or_mask
            new_has = has_any or (digit == 1)
            result = (result + dp(pos - 1, new_tight, new_or, new_has)) % MOD

        memo[(pos, tight, or_mask, has_any)] = result
        return result

    return dp(bits - 1, True, 0, False)

