def maxGoodSubsequence(nums, k):
    n = len(nums)

    # dp[i][j] = max length of good subsequence ending at index i with j transitions
    dp = [[0] * (k + 1) for _ in range(n)]

    # Base case
    dp[0][0] = 1

    for i in range(n):
        for j in range(k + 1):
            if i > 0 and dp[i-1][j] > 0 and nums[i] == nums[i-1]:
                # Can extend the previous subsequence if the values are the same
                dp[i][j] = max(dp[i][j], dp[i-1][j] + 1)
            elif j > 0:
                # Need to use a transition
                for prev in range(i):
                    if dp[prev][j-1] > 0 or (j == 1 and prev == 0):
                        dp[i][j] = max(dp[i][j], dp[prev][j-1] + 1)

            # Starting fresh at position i with 0 transitions
            if j == 0:
                dp[i][0] = 1

    ans = 0
    for i in range(n):
        for j in range(k + 1):
            ans = max(ans, dp[i][j])

    return ans

def maxGoodSubsequence_v2(nums, k):
    n = len(nums)
    # dp[i][changes] = maximum length of good subsequence using first i elements with 'changes' transitions
    dp = {}

    def solve(idx, changes, last_val):
        if changes < 0:
            return -float('inf')
        if idx == n:
            return 0

        if (idx, changes, last_val) in dp:
            return dp[(idx, changes, last_val)]

        # Option 1: Don't include current element
        result = solve(idx + 1, changes, last_val)

        # Option 2: Include current element
        if last_val == -1:  # First element
            result = max(result, 1 + solve(idx + 1, changes, nums[idx]))
        elif nums[idx] == last_val:  # Same value, no transition
            result = max(result, 1 + solve(idx + 1, changes, nums[idx]))
        else:  # Different value, need a transition
            result = max(result, 1 + solve(idx + 1, changes - 1, nums[idx]))

        dp[(idx, changes, last_val)] = result
        return result

    return solve(0, k, -1)

def maxGoodSubsequence_v3(nums, k):
    n = len(nums)
    # dp[i][j] = max length of good subsequence ending at index i with exactly j transitions
    # transitions happen when consecutive elements in the subsequence are different

    dp = [[0] * (k + 2) for _ in range(n)]

    # Base case: each element by itself is a valid subsequence with 0 transitions
    for i in range(n):
        dp[i][0] = 1

    for i in range(n):
        for j in range(i + 1, n):
            for changes in range(k + 1):
                if dp[i][changes] > 0:
                    # Add nums[j] to subsequence ending at nums[i]
                    if nums[i] != nums[j]:
                        # Need one more change
                        if changes + 1 <= k:
                            dp[j][changes + 1] = max(dp[j][changes + 1], dp[i][changes] + 1)
                    else:
                        # Same value, no additional change needed
                        dp[j][changes] = max(dp[j][changes], dp[i][changes] + 1)

    ans = 0
    for i in range(n):
        for j in range(k + 1):
            ans = max(ans, dp[i][j])

    return ans

