def bfs(n, graph):
    if n == 1:
        return 0

    queue = deque([0])
    visited = [False] * n
    visited[0] = True
    dist = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            node = queue.popleft()
            if node == n - 1:
                return dist
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        dist += 1

    return dist

