    def dp(row, col, neutralizations_left):
        if row >= m or col >= n:
            return float('-inf')

        if row == m - 1 and col == n - 1:
            return max(0, coins[row][col])

        current_value = coins[row][col]

        down = dp(row + 1, col, neutralizations_left)
        right = dp(row, col + 1, neutralizations_left)

        if down == float('-inf') and right == float('-inf'):
            return float('-inf')

        if down == float('-inf'):
            best_next = right
        elif right == float('-inf'):
            best_next = down
        else:
            best_next = max(down, right)

        if current_value >= 0:
            return current_value + best_next
        else:
            result = current_value + best_next

            if neutralizations_left > 0:
                down_neutralized = dp(row + 1, col, neutralizations_left - 1)
                right_neutralized = dp(row, col + 1, neutralizations_left - 1)

                if down_neutralized == float('-inf') and right_neutralized == float('-inf'):
                    result = max(result, float('-inf'))
                elif down_neutralized == float('-inf'):
                    result = max(result, best_next)
                elif right_neutralized == float('-inf'):
                    result = max(result, best_next)
                else:
                    result = max(result, best_next)

