def find_min_max(target, L):
    max_B = target

    while max_B >= 0:
        found = False

        def backtrack(idx, current_B, current_sum):
            nonlocal found

            if found:
                return

            if idx == L:
                if current_sum == target:
                    found = True
                return

            if current_sum > target:
                return

            remaining = L - idx
            remaining_pairs = remaining * (remaining - 1) // 2
            if remaining_pairs > 0:
                max_possible_per_pair = (target - current_sum) // remaining_pairs
            else:
                max_possible_per_pair = max_B

            for val in range(min(max_B, max_possible_per_pair) + 1):
                new_sum = current_sum
                for prev_val in current_B:
                    new_sum += abs(prev_val - val)

                if new_sum <= target:
                    backtrack(idx + 1, current_B + [val], new_sum)
                    if found:
                        return

        backtrack(0, [], 0)

        if found:
            return max_B

        max_B -= 1

    return -1

