    lo, hi = 0, target
    answer = -1

    while lo <= hi:
        mid = (lo + hi) // 2

        found = False

        def backtrack(idx, current_B, current_sum):
            nonlocal found

            if found:
                return

            if idx == L:
                if current_sum == target:
                    found = True
                return

            if current_sum > target:
                return

            for val in range(mid + 1):
                new_sum = current_sum
                for prev_val in current_B:
                    new_sum += abs(prev_val - val)

                if new_sum <= target:
                    backtrack(idx + 1, current_B + [val], new_sum)
                    if found:
                        return

        backtrack(0, [], 0)

        if found:
            answer = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return answer

