def price(num, x):
    count = 0
    pos = 1
    while pos <= num.bit_length():
        if pos % x == 0:
            if num & (1 << (pos - 1)):
                count += 1
        pos += 1
    return count

def count_bits_at_positions(n, x):
    if n <= 0:
        return 0

    total = 0
    bit_len = n.bit_length()

    for pos in range(x, bit_len + 1, x):
        bit_pos = pos - 1
        cycle = 1 << (bit_pos + 1)
        complete_cycles = (n + 1) // cycle
        remainder = (n + 1) % cycle

        total += complete_cycles * (cycle // 2)
        if remainder > (1 << bit_pos):
            total += remainder - (1 << bit_pos)

    return total

