def solve(n, x, k, s):
    if k == 0:
        return float('inf')

    total_zeros = s.count('0')
    total_ones = s.count('1')

    if total_zeros == 0 or total_ones == 0:
        return 1

    max_inversions = 0
    i = 0
    while i <= x:
        if i % k == 0:
            max_inversions = i
        i += 1
        if i > x:
            break

    if max_inversions == 0 and x >= 0 and 0 % k == 0:
        max_inversions = 0
    elif max_inversions == 0:
        return float('inf')

    ones_count = 0
    min_ops = float('inf')

    for mask in range(1, 1 << n):
        subseq = []
        for i in range(n):
            if mask & (1 << i):
                subseq.append(s[i])

        inversions = 0
        ones_in_subseq = 0
        for char in subseq:
            if char == '1':
                ones_in_subseq += 1
            else:
                inversions += ones_in_subseq

        if inversions <= x and inversions % k == 0:
            remaining = []
            for i in range(n):
                if not (mask & (1 << i)):
                    remaining.append(s[i])

            if len(remaining) == 0:
                min_ops = 1
                break

    if min_ops == 1:
        return 1

    max_allowed = (x // k) * k

    ones = 0
    operations = 1

    for char in s:
        if char == '1':
            ones += 1
        else:
            if ones > max_allowed:
                operations += 1
                ones = 0

    return operations

