def solve(words):
    char_count = Counter()
    for word in words:
        for char in word:
            char_count[char] += 1

    lengths = [len(word) for word in words]
    lengths.sort(reverse=True)

    total_chars = sum(char_count.values())

    result = 0
    char_pool = dict(char_count)

    for length in lengths:
        if length % 2 == 0:
            needed_pairs = length // 2
            available_pairs = sum(count // 2 for count in char_pool.values())
            if available_pairs >= needed_pairs:
                result += 1
                remaining = needed_pairs
                for char in list(char_pool.keys()):
                    if remaining == 0:
                        break
                    pairs_from_char = min(char_pool[char] // 2, remaining)
                    char_pool[char] -= pairs_from_char * 2
                    remaining -= pairs_from_char
                    if char_pool[char] == 0:
                        del char_pool[char]
        else:
            needed_pairs = length // 2
            available_pairs = sum(count // 2 for count in char_pool.values())
            has_odd = any(count % 2 == 1 for count in char_pool.values())

            if available_pairs >= needed_pairs and has_odd:
                result += 1
                remaining = needed_pairs
                for char in list(char_pool.keys()):
                    if remaining == 0:
                        break
                    pairs_from_char = min(char_pool[char] // 2, remaining)
                    char_pool[char] -= pairs_from_char * 2
                    remaining -= pairs_from_char
                    if char_pool[char] == 0:
                        del char_pool[char]

                found_odd = False
                for char in list(char_pool.keys()):
                    if char_pool[char] % 2 == 1:
                        char_pool[char] -= 1
                        found_odd = True
                        if char_pool[char] == 0:
                            del char_pool[char]
                        break

    return result

