def solve(n, records):
    min_changes = 2 * n

    def backtrack(index, current_records, changes):
        nonlocal min_changes

        if changes >= min_changes:
            return

        if index == n:
            if is_valid_ranking(current_records):
                min_changes = min(min_changes, changes)
            return

        x, y = records[index]

        for ny in range(n):
            for nx in range(n):
                new_records = current_records + [(ny, nx)]
                new_changes = changes + (0 if (x == nx and y == ny) else 1)

                valid = True
                for i in range(index):
                    yi, xi = new_records[i]
                    yj, xj = new_records[index]
                    if yi < yj or (yi == yj and xi < xj):
                        valid = False
                        break

                if valid:
                    backtrack(index + 1, new_records, new_changes)

    backtrack(0, [], 0)
    return min_changes

