def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find_parent(parent, x)
    py = find_parent(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        px, py = py, px
    parent[py] = px
    if rank[px] == rank[py]:
        rank[px] += 1
    return True

def compute_f(N, edges, u, v):
    sorted_edges = sorted(edges, key=lambda x: x[2])
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    for edge_u, edge_v, w in sorted_edges:
        union(parent, rank, edge_u, edge_v)
        if find_parent(parent, u) == find_parent(parent, v):
            return w
    return float('inf')

def min_cost_matching(costs, K):
    INF = float('inf')
    n = K
    dp = [INF] * (1 << n)
    dp[0] = 0

    for mask in range(1 << n):
        if dp[mask] == INF:
            continue
        i = bin(mask).count('1')
        if i >= n:
            continue
        for j in range(n):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << j)
                dp[new_mask] = min(dp[new_mask], dp[mask] + costs[i][j])

    return dp[(1 << n) - 1]

