        if char not in char_runs:
            char_runs[char] = []
        char_runs[char].append(length)

    # For each character, find the longest special substring that occurs at least 3 times
    for char, runs in char_runs.items():
        # For a run of length L, we can get special substrings of length 1, 2, ..., L
        # A substring of length k from a run of length L appears (L - k + 1) times

        # For each possible length k, count how many times it appears
        for k in range(1, max(runs) + 1):
            count = 0
            for run_len in runs:
                if run_len >= k:
                    count += run_len - k + 1

            if count >= 3:
                max_len = max(max_len, k)

    return max_len

