import sys
from math import log2

def get_powerful_array(x):
    if x == 0:
        return []
    powers = []
    bit_pos = 0
    while x > 0:
        if x & 1:
            powers.append(1 << bit_pos)
        x >>= 1
        bit_pos += 1
    return powers

def count_bits_up_to_n(n):
    if n < 0:
        return [0] * 64
    counts = [0] * 64
    bit_length = n.bit_length()

    for bit in range(bit_length):
        full_cycles = (n + 1) // (1 << (bit + 1))
        counts[bit] = full_cycles * (1 << bit)
        remainder = (n + 1) % (1 << (bit + 1))
        if remainder > (1 << bit):
            counts[bit] += remainder - (1 << bit)

    return counts

def count_bits_in_range(from_idx, to_idx):
    if from_idx > to_idx:
        return [0] * 64

    def find_num_and_offset(idx):
        if idx == 0:
            return 0, 0
        left, right = 1, idx + 1
        while left < right:
            mid = (left + right + 1) // 2
            total = mid * (mid.bit_count() if hasattr(mid, 'bit_count') else bin(mid).count('1'))
            if total <= idx:
                left = mid
            else:
                right = mid - 1

        num = left
        offset_before = num * bin(num).count('1')
        offset_in_num = idx - offset_before
        return num, offset_in_num

    num_start, offset_start = find_num_and_offset(from_idx)
    num_end, offset_end = find_num_and_offset(to_idx)

    counts = [0] * 64

    if num_start == num_end:
        powers = get_powerful_array(num_start)
        for i in range(offset_start, offset_end + 1):
            bit_pos = (powers[i]).bit_length() - 1
            counts[bit_pos] += 1
    else:
        powers_start = get_powerful_array(num_start)
        for i in range(offset_start, len(powers_start)):
            bit_pos = (powers_start[i]).bit_length() - 1
            counts[bit_pos] += 1

        if num_end > num_start + 1:
            bit_counts = count_bits_up_to_n(num_end - 1)
            bit_counts_before = count_bits_up_to_n(num_start)
            for bit in range(64):
                counts[bit] += bit_counts[bit] - bit_counts_before[bit]

        powers_end = get_powerful_array(num_end)
        for i in range(offset_end + 1):
            bit_pos = (powers_end[i]).bit_length() - 1
            counts[bit_pos] += 1

    return counts

def solve_query(from_idx, to_idx, mod):
    counts = count_bits_in_range(from_idx, to_idx)

    result = 1
    for bit in range(64):
        if counts[bit] > 0:
            power = (1 << bit) % mod
            result = (result * pow(power, counts[bit], mod)) % mod

    return result

