import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def calculate_gcd(arr):
    if not arr:
        return 0
    return reduce(gcd, arr)

def calculate_lcm(arr):
    if not arr:
        return 0
    return reduce(lcm, arr)

def max_factor_score(nums):
    if not nums:
        return 0

    max_score = 0

    # Try without removing any element
    current_gcd = calculate_gcd(nums)
    current_lcm = calculate_lcm(nums)
    max_score = current_gcd * current_lcm

    # Try removing each element
    for i in range(len(nums)):
        remaining = nums[:i] + nums[i+1:]

        if not remaining:
            # If we remove all elements, score is 0
            continue

        current_gcd = calculate_gcd(remaining)
        current_lcm = calculate_lcm(remaining)
        score = current_gcd * current_lcm
        max_score = max(max_score, score)

    return max_score

