import sys
from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(values):
    if not values or values[0] is None:
        return None

    root = TreeNode(values[0])
    queue = deque([root])
    i = 1

    while queue and i < len(values):
        node = queue.popleft()

        if i < len(values) and values[i] is not None:
            node.left = TreeNode(values[i])
            queue.append(node.left)
        i += 1

        if i < len(values) and values[i] is not None:
            node.right = TreeNode(values[i])
            queue.append(node.right)
        i += 1

    return root

def is_perfect_subtree(node):
    if not node:
        return True, 0, 0

    if not node.left and not node.right:
        return True, 1, 0

    if not node.left or not node.right:
        return False, 0, 0

    left_perfect, left_size, left_height = is_perfect_subtree(node.left)
    right_perfect, right_size, right_height = is_perfect_subtree(node.right)

    if left_perfect and right_perfect and left_height == right_height:
        return True, left_size + right_size + 1, left_height + 1
    else:
        return False, 0, 0

def find_all_perfect_sizes(node, sizes):
    if not node:
        return

    is_perfect, size, height = is_perfect_subtree(node)
    if is_perfect:
        sizes.append(size)

    find_all_perfect_sizes(node.left, sizes)
    find_all_perfect_sizes(node.right, sizes)

def kth_largest_perfect_subtree(root, k):
    sizes = []
    find_all_perfect_sizes(root, sizes)
    sizes.sort(reverse=True)

    if k <= len(sizes):
        return sizes[k - 1]
    else:
        return -1

