import sys

def compress(s):
    n = len(s)
    if n == 0:
        return ""

    # dp[i][j] = shortest representation of s[i:j+1]
    dp = {}

    def solve(i, j):
        if i > j:
            return ""
        if i == j:
            return s[i]

        if (i, j) in dp:
            return dp[(i, j)]

        # Option 1: No compression, just concatenate optimal substrings
        result = s[i:j+1]  # Start with the literal string

        # Try splitting at each position
        for k in range(i, j):
            left = solve(i, k)
            right = solve(k+1, j)
            candidate = left + right
            if len(candidate) < len(result):
                result = candidate

        # Option 2: Try to find a repeating pattern
        length = j - i + 1
        substring = s[i:j+1]

        # Try each possible pattern length
        for plen in range(1, length + 1):
            if length % plen == 0:
                pattern = substring[:plen]
                reps = length // plen
                if pattern * reps == substring and reps >= 2 and reps <= 9:
                    # Direct repetition
                    compressed_pattern = solve(i, i + plen - 1)
                    candidate = str(reps) + "(" + compressed_pattern + ")"
                    if len(candidate) < len(result):
                        result = candidate

        # Option 3: Try nested repetitions (for cases like 6(5(a)))
        for plen in range(1, length + 1):
            if length % plen == 0:
                pattern = substring[:plen]
                reps = length // plen
                if pattern * reps == substring and reps > 9:
                    # Need nested repetitions
                    for outer in range(2, 10):
                        if reps % outer == 0:
                            inner = reps // outer
                            if inner >= 2 and inner <= 9:
                                compressed_pattern = solve(i, i + plen - 1)
                                candidate = str(outer) + "(" + str(inner) + "(" + compressed_pattern + "))"
                                if len(candidate) < len(result):
                                    result = candidate
                            elif inner > 9:
                                # Try further nesting
                                for outer2 in range(2, 10):
                                    if inner % outer2 == 0:
                                        inner2 = inner // outer2
                                        if inner2 >= 2 and inner2 <= 9:
                                            compressed_pattern = solve(i, i + plen - 1)
                                            candidate = str(outer) + "(" + str(outer2) + "(" + str(inner2) + "(" + compressed_pattern + ")))"
                                            if len(candidate) < len(result):
                                                result = candidate

        dp[(i, j)] = result
        return result

    return solve(0, n - 1)

