def flip(c):
    if c.islower():
        return c.upper()
    else:
        return c.lower()

def find_char(S, K):
    n = len(S)
    flip_count = 0

    while K > n:
        K -= n
        n *= 2
        flip_count += 1

    pos = K - 1
    char = S[pos]

    for _ in range(flip_count):
        char = flip(char)

    return char

