import sys

def balikon_to_int(s):
    if s == "ze":
        return 0

    parts = []
    current = ""
    for char in s:
        current += char
        if current in ["shas", "tas", "tes", "tos", "les", "lons", "shons", "shatas", "shalons", "lonshons", "lonshatas", "lonshalons", "shonshons", "shonshatas", "shonshalons", "shatashons", "shatashatas", "shatashalons", "shalonshons", "shalonshatas", "shalonshalons"]:
            parts.append(current)
            current = ""
        elif current in ["lon", "sha", "sho"]:
            continue

    mapping = {
        "ze": 0,
        "tes": 1,
        "les": 2,
        "tos": 3,
        "shas": 4,
        "shons": 5,
        "tas": 6,
        "tes": 7,
        "lons": 8,
        "shatas": 9
    }

    num_map = {
        "ze": 0, "tes": 1, "les": 2, "tos": 3, "shas": 4,
        "shons": 5, "tas": 6, "lons": 8, "shatas": 9
    }

    def parse(s):
        if s in num_map:
            return num_map[s]

        if s.startswith("lon"):
            rest = s[3:]
            return 10 + parse(rest)
        if s.startswith("sha"):
            if s.startswith("shons"):
                return 5
            if s.startswith("shatas"):
                return 9
            if s.startswith("shalons"):
                rest = s[7:]
                return 30 + parse(rest)
            if s.startswith("shas"):
                return 4
            rest = s[3:]
            return 20 + parse(rest)
        if s.startswith("sho"):
            if s.startswith("shons"):
                return 5
            rest = s[4:]
            return 50 + parse(rest)

        return 0

    return parse(s)

def int_to_balikon(n):
    if n == 0:
        return "ze"

    num_map = {
        0: "ze", 1: "tes", 2: "les", 3: "tos", 4: "shas",
        5: "shons", 6: "tas", 7: "tes", 8: "lons", 9: "shatas"
    }

    if n < 10:
        if n == 7:
            return "tes"
        return num_map.get(n, "")

    if n < 20:
        ones = n - 10
        if ones == 0:
            return "lon"
        return "lon" + int_to_balikon(ones)

    if n < 50:
        tens = n - 20
        if tens == 0:
            return "sha"
        return "sha" + int_to_balikon(tens)

    if n < 100:
        tens = n - 50
        if tens == 0:
            return "shon"
        return "shon" + int_to_balikon(tens)

    hundreds = n // 100
    remainder = n % 100
    result = int_to_balikon(hundreds) + "sha"
    if remainder > 0:
        result += int_to_balikon(remainder)
    return result

