    return s == s[::-1]

def get_palindromic_candidates(nums):
    candidates = set()

    min_num = min(nums)
    max_num = max(nums)

    for num in nums:
        candidates.add(num)

    for i in range(1, 10):
        candidates.add(i)

    for i in range(10, 100):
        if is_palindromic(i):
            candidates.add(i)

    start = max(1, min_num - 1000)
    end = min(10**9, max_num + 1000)

    s = str(min_num)
    for length in range(len(s), len(s) + 2):
        for i in range(10**(length-1), min(10**length, end + 1)):
            if is_palindromic(i):
                candidates.add(i)

    s = str(max_num)
    for length in range(max(1, len(s) - 1), len(s) + 2):
        for i in range(max(1, 10**(length-1)), min(10**length, end + 1)):
            if is_palindromic(i):
                candidates.add(i)

    candidates = [c for c in candidates if 1 <= c < 10**9]

    return candidates

def calculate_cost(nums, target):
    return sum(abs(num - target) for num in nums)

def solve(nums):
    if len(nums) == 1:
        if is_palindromic(nums[0]):
            return 0
        min_cost = float('inf')
        for candidate in range(1, 10**9):
            if is_palindromic(candidate):
                cost = abs(nums[0] - candidate)
                min_cost = min(min_cost, cost)
                if cost > min_cost:
                    break
        return min_cost

    candidates = get_palindromic_candidates(nums)

    if not candidates:
        candidates = [i for i in range(1, 10**9) if is_palindromic(i)][:1000]

    min_cost = float('inf')
    for candidate in candidates:
        cost = calculate_cost(nums, candidate)
        min_cost = min(min_cost, cost)

