MOD = 10**9 + 7

def mod_factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def solve(n, k):
    if k < 3 or k > 2 * n - 1:
        return 0

    if k > n:
        a = k - n
        b = 2 * n - k
        if a < 1 or b < 1 or a > n or b > n:
            return 0
        if a + b != k:
            return 0
        count_pairs = 1
    else:
        a = k - 1
        b = 1
        if a < 1 or a > n:
            return 0
        count_pairs = 1

    total_pairs = count_pairs

    remaining = n - 2 * total_pairs

    if remaining < 0:
        return 0

    total = (2 * mod_factorial(n - total_pairs, MOD)) % MOD

    return total

